// Processar e validar dados do lead
const leadData = $input.first().json;

// Calcular score do lead
function calculateLeadScore(data) {
  let score = 50;

  const planScores = {
    'Exclusivo': 40,
    'Premium': 30,
    'Profissional': 20,
    'Padrão': 10
  };

  score += planScores[data.selectedServicePlan] || 0;

  if (data.promoActive) score += 15;
  if (data.userMessage && data.userMessage.length > 50) score += 10;
  if (data.userEnterprise.length > 10) score += 5;

  return Math.min(score, 100);
}

// Processar dados
const processedData = {
  // Dados do lead
  leadId: `lead_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  name: leadData.userName,
  enterprise: leadData.userEnterprise,
  phone: leadData.userNumber,
  selectedPlan: leadData.selectedServicePlan,
  message: leadData.userMessage || 'Sem mensagem adicional',
  promoActive: leadData.promoActive || false,

  // Metadata
  leadScore: calculateLeadScore(leadData),
  source: 'website_komprax',
  timestamp: new Date().toISOString(),
  ip: leadData.metadata?.ip || 'unknown',
  userAgent: leadData.metadata?.userAgent || 'unknown',

  // Classificação automática
  priority: calculateLeadScore(leadData) >= 80 ? 'HIGH' : 
           calculateLeadScore(leadData) >= 60 ? 'MEDIUM' : 'LOW',

  // Próximos passos
  nextSteps: [
    'Análise das necessidades específicas',
    'Preparação de demonstração personalizada',
    leadData.selectedServicePlan === 'Exclusivo' ? 
      'Contato de consultor sênior para orçamento personalizado' :
      `Demonstração do plano ${leadData.selectedServicePlan}`,
    leadData.promoActive ? '🔥 Aplicação do desconto promocional' : null
  ].filter(Boolean)
};

return { json: processedData };

