// Gerar resposta inteligente baseada no perfil do lead
const leadData = $input.first().json;

function generateIntelligentResponse(data) {
  const responses = {
    'Exclusivo': {
      message: `Olá ${data.name}! Que excelente escolha o plano Exclusivo! 🌟 Nossa equipe de consultores sêniores entrará em contato nas próximas 2 horas para desenvolver uma solução completamente personalizada para ${data.enterprise}.`,
      urgency: 'IMMEDIATE',
      assignTo: 'senior_consultant'
    },
    'Premium': {
      message: `${data.name}, obrigado pelo interesse no plano Premium! 🚀 Este é perfeito para associações de médio-grande porte. Nosso especialista entrará em contato hoje para uma demonstração completa.`,
      urgency: 'HIGH',
      assignTo: 'product_specialist'
    },
    'Profissional': {
      message: `Oi ${data.name}! O plano Profissional é uma excelente opção para ${data.enterprise}. ⚡ Vamos agendar uma demonstração para mostrar como pode otimizar suas operações.`,
      urgency: 'MEDIUM',
      assignTo: 'sales_consultant'
    },
    'Padrão': {
      message: `Olá ${data.name}! O plano Padrão é ideal para começar a transformação digital de ${data.enterprise}. 📈 Nossa equipe entrará em contato para mostrar os primeiros passos.`,
      urgency: 'NORMAL',
      assignTo: 'sales_rep'
    }
  };

  const response = responses[data.selectedPlan] || responses['Padrão'];

  // Adicionar urgência se promoção ativa
  if (data.promoActive) {
    response.message += " 🔥 E como você tem a promoção ativa, vamos garantir que receba o desconto especial!";
    response.urgency = 'IMMEDIATE';
  }

  return response;
}

const aiResponse = generateIntelligentResponse(leadData);

return {
  json: {
    ...leadData,
    aiResponse: aiResponse,
    automatedTasks: [
      {
        type: 'followup_call',
        scheduledFor: new Date(Date.now() + (aiResponse.urgency === 'IMMEDIATE' ? 2 * 60 * 60 * 1000 : 24 * 60 * 60 * 1000)).toISOString(),
        assignedTo: aiResponse.assignTo,
        priority: aiResponse.urgency
      },
      {
        type: 'send_material',
        scheduledFor: new Date(Date.now() + 30 * 60 * 1000).toISOString(), // 30 min
        material: `brochure_${leadData.selectedPlan.toLowerCase()}`,
        priority: 'NORMAL'
      }
    ]
  }
};
